mapper.select:
select ad.document_id as documentId , ad.writer_id as writerId , ad.fault_id as faultId , ad.inspection_id as inspectionId , ad.document_type as documentType , ad.title , ad.content , ad.estimated_cost as estimatedCost , ad.status , ad.created_at as createdAt , ad.updated_at as updatedAt , ad.completed_at as completedAt , wm.member_name as writerName , we.employee_no as writerEmployeeNo , wm.user_type as writerUserType , wd.department_name as writerDepartmentName , we.position_name as writerPositionName , f.title as faultTitle , f.status as faultStatus , f.severity as faultSeverity , s.station_name as stationName , c.charger_name as chargerName , c.charger_type as chargerType , c.connector_type as connectorType , c.status as chargerStatus , i.inspection_result as inspectionResult , i.description as inspectionDescription , pending.approver_id as currentApproverId , pending_member.member_name as currentApproverName , pending_member.user_type as currentApproverUserType from approval_document ad join employee we on ad.writer_id = we.employee_id join app_member wm on we.member_id = wm.member_id left join department wd on we.department_id = wd.department_id left join fault_report f on ad.fault_id = f.fault_id left join charging_station s on f.station_id = s.station_id left join charger c on f.charger_id = c.charger_id left join inspection i on ad.inspection_id = i.inspection_id left join lateral ( select al.* from approval_line al where al.document_id = ad.document_id and al.status = '대기' order by al.approval_order asc limit 1 ) pending on true left join employee pending_employee on pending.approver_id = pending_employee.employee_id left join app_member pending_member on pending_employee.member_id = pending_member.member_id where 1 = 1
and pending.approver_id = #{currentEmployeeId}
and ad.writer_id = #{currentEmployeeId}
and ad.status in ('상신', '1차승인')
and ad.status in ('최종승인', '완료', '반려', '취소')
and ad.writer_id = #{currentEmployeeId}
and ad.status = #{status}
and ( ad.title ilike concat('%', #{keyword}, '%') or ad.document_type ilike concat('%', #{keyword}, '%') or wm.member_name ilike concat('%', #{keyword}, '%') or coalesce(s.station_name, '') ilike concat('%', #{keyword}, '%') or coalesce(c.charger_name, '') ilike concat('%', #{keyword}, '%') )
order by ad.created_at desc, ad.document_id desc

mapper.insert:
insert into approval_document (
      writer_id
    , fault_id
    , inspection_id
    , document_type
    , title
    , content
    , estimated_cost
    , status
    , created_at
    , updated_at
) values (
      #{document.writerId}
    , #{document.faultId}
    , #{document.inspectionId}
    , #{document.documentType}
    , #{document.title}
    , #{document.content}
    , #{document.estimatedCost}
    , #{document.status}
    , current_timestamp
    , current_timestamp
)

insert into approval_line (
      document_id
    , approver_id
    , approval_order
    , status
) values (
      #{documentId}
    , #{approverId}
    , #{approvalOrder}
    , '대기'
)

insert into approval_history (
      document_id
    , employee_id
    , action_type
    , before_status
    , after_status
    , comment
    , created_at
) values (
      #{documentId}
    , #{employeeId}
    , #{actionType}
    , #{beforeStatus}
    , #{afterStatus}
    , #{comment}
    , current_timestamp
)

insert into fault_history (
      fault_id
    , employee_id
    , before_status
    , after_status
    , action_type
    , memo
    , created_at
)
select
      ad.fault_id
    , #{employeeId}
    , #{beforeStatus}
    , #{afterStatus}
    , #{actionType}
    , #{memo}
    , current_timestamp
  from approval_document ad
 where ad.document_id = #{documentId}
   and ad.fault_id is not null

mapper.select:
select coalesce(sum(estimated_cost), 0)
  from approval_document
 where status = #{status}
